import { useEffect } from 'react';

/**
 * Stop the page scrolling without the jump: hiding the overflow drops the page's
 * scrollbar, so the gutter it occupied is kept reserved while the lock holds.
 * Returns the restore function.
 */
export const lockPageScroll = (): (() => void) => {
    const root = document.documentElement;
    const previous = { root: root.style.overflow, body: document.body.style.overflow };
    // Only a gutter this lock reserved is its to release; the host integration keeps its own.
    const reserve = !root.style.scrollbarGutter && window.innerWidth > root.clientWidth;
    if (reserve) root.style.scrollbarGutter = 'stable';
    root.style.overflow = 'hidden';
    document.body.style.overflow = 'hidden';
    return () => {
        root.style.overflow = previous.root;
        document.body.style.overflow = previous.body;
        if (reserve) root.style.scrollbarGutter = '';
    };
};

/**
 * Hook to lock body scroll when a modal/overlay is open
 * @param isLocked - Whether to lock the body scroll
 */
export const useBodyScrollLock = (isLocked: boolean): void => {
    useEffect(() => (isLocked ? lockPageScroll() : undefined), [isLocked]);
};

export default useBodyScrollLock;
