/**
 * Page chrome while the search is open: the `body.ai-search-active` class, the
 * scrollbar gutter it needs, and where focus returns on close. Shared by the
 * integration and the container, which reopens the search from the results page.
 */

// Closing the search returns focus beside the box that opened it: to its form's
// submit button. Not the box itself, whose focus is what opens the search, so a
// click on the already-focused box would do nothing.
const RETURN_FOCUS = 'data-omniguide-return-focus';

const SUBMIT = 'button[type="submit"], input[type="submit"], button:not([type])';

// NOTE: rememberOpener / forgetOpener are duplicated in `@swiftotter/omniguide-bundle`'s
// search-trigger.ts, which must not import this package (it ships in the loader chunk).
export function rememberOpener(input: HTMLElement): void {
  forgetOpener();
  input.setAttribute(RETURN_FOCUS, '');
}

export function forgetOpener(): void {
  document.querySelectorAll(`[${RETURN_FOCUS}]`).forEach((el) => el.removeAttribute(RETURN_FOCUS));
}

// One-shot: a later search opened any other way must not pull focus (and the
// scroll position) back up to the header box.
export function restoreFocus(): void {
  const input = document.querySelector<HTMLInputElement>(`[${RETURN_FOCUS}]`);
  forgetOpener();
  input?.form?.querySelector<HTMLElement>(SUBMIT)?.focus({ preventScroll: true });
}

// `body.ai-search-active` hides the page's overflow, which drops its scrollbar;
// the gutter stays reserved (measured before the class lands) so nothing jumps.
// Only a gutter we set is released — a host's own inline value is left alone.
// NOTE: duplicated in `@swiftotter/omniguide-bundle`'s search-trigger.ts.
let reservedGutter = false;

export function activateSearchBody(websiteId: string): void {
  const root = document.documentElement;
  if (!root.style.scrollbarGutter && window.innerWidth > root.clientWidth) {
    root.style.scrollbarGutter = 'stable';
    reservedGutter = true;
  }
  document.body.classList.add('ai-search-active');
  document.body.setAttribute('data-omniguide-search', websiteId);
}

export function deactivateSearchBody(): void {
  document.body.classList.remove('ai-search-active');
  document.body.removeAttribute('data-omniguide-search');
  if (reservedGutter) document.documentElement.style.scrollbarGutter = '';
  reservedGutter = false;
}
