/**
 * BCSearchIntegration — DOM integration for AI search in BigCommerce Stencil themes.
 *
 * Ported from theme `search/index.js`.
 * Creates container div, mounts BCSearchContainer via createRoot.
 * Overrides desktop/mobile/WordPress search behavior.
 */

import React from 'react';
import { flushSync } from 'react-dom';
import { createRoot, type Root } from 'react-dom/client';
import { OmniguideProvider, type OmniguideProviderProps } from '@swiftotter/omniguide-react';
import type { OmniguideComponentOverrides } from '@swiftotter/omniguide-react';
import type { OmniguideConfig, PlatformAdapter, StorageAdapter, SearchIntegration } from '@swiftotter/omniguide-core';
import { BCSearchContainer } from '../containers/BCSearchContainer.js';
import { BCMobileSearchIntegration } from './BCMobileSearchIntegration.js';
import { activateSearchBody, deactivateSearchBody, forgetOpener, rememberOpener, restoreFocus } from './searchBody.js';

// ── Types ──────────────────────────────────────────────────────────

export interface BCSearchIntegrationConfig {
  config: OmniguideConfig;
  platformAdapter: PlatformAdapter;
  storageAdapter?: StorageAdapter;
  /** Custom container component (replaces BCSearchContainer entirely) */
   
  ContainerComponent?: React.ComponentType<any>;
  /** Sub-component overrides passed to OmniguideProvider */
  components?: OmniguideComponentOverrides;
  /**
   * Skip DOM setup (icon swap, search behavior override, mobile integration).
   * When true, only creates container + mounts React component + hides default search.
   * Used by ESM loader which handles trigger setup independently.
   */
  skipDomSetup?: boolean;
}

// ── Data attribute for preventing double-mount ──────────────────────

const MOUNTED_ATTR = 'data-omniguide-mounted';

// ── Search icon swap ────────────────────────────────────────────────
// NOTE: the helpers below are duplicated in `@swiftotter/omniguide-bundle`'s
// search-trigger.ts, which serves the ESM-loader and custom-trigger paths while
// this serves the default BigCommerce path. Deduplicating them into
// `omniguide-core` is possible — core already ships dom.ts — but would relax
// search-trigger.ts's zero-imports header contract, so it is a deliberate
// deferral rather than an impossibility. `readHostIconStyle`,
// `buildDefaultIcon`, `sizeDefaultIcon`, `applyHostFill` and `alignIconToHost`
// are byte-identical in both files and must stay that way. This path accepts no
// caller-supplied icon, so it has no equivalent of the bundle copy's
// `parseSvg` / `resolveReplacementIcon`.

/** Square viewBox of the built-in glyph, and the box it declares. */
const SEARCH_ICON_VIEWBOX = '0 0 20.5627 20.5674';
const SEARCH_ICON_BOX = '21';

/**
 * The artwork itself. Both paths paint with `fill` and set no `stroke`, and the
 * viewBox is square — which is what lets the replacement be kept square and
 * fill-only regardless of how the host icon was drawn.
 */
const SEARCH_ICON_PATHS = `<path d="M9.4953 2C8.01204 2 6.56162 2.43967 5.32831 3.26367C2.83318 4.93087 1.55452 8.01993 2.13983 10.9629C2.42923 12.4177 3.14271 13.7548 4.19159 14.8037C6.31348 16.9255 9.59339 17.5769 12.3654 16.4287C15.1387 15.2798 16.9953 12.5021 16.9953 9.5H18.9953C18.9953 10.8103 18.7176 12.1086 18.197 13.3018C17.5727 14.7328 17.593 16.4891 18.6971 17.5929L20.5627 19.458L19.4533 20.5674L17.5853 18.6994C16.4819 17.5959 14.7266 17.5782 13.292 18.1923C9.7981 19.6879 5.55216 18.9923 2.77753 16.2178C1.44898 14.8892 0.544506 13.1962 0.177917 11.3535C-0.563569 7.62581 1.05663 3.71231 4.21698 1.60059C5.77919 0.55682 7.61648 0 9.4953 0V2Z" fill="currentColor"/>
  <path d="M13.7531 0.0488281C13.8338 4.32301 14.6717 5.16046 18.9455 5.24121C19.0082 5.73809 19.0081 6.26091 18.9455 6.75781C14.6719 6.83856 13.8339 7.67665 13.7531 11.9502C13.2563 12.0129 12.7333 12.0129 12.2365 11.9502C12.1558 7.67642 11.3183 6.83848 7.04413 6.75781C6.98149 6.26096 6.98141 5.73804 7.04413 5.24121C11.3185 5.16054 12.1558 4.32324 12.2365 0.0488281C12.7333 -0.0138614 13.2563 -0.0138114 13.7531 0.0488281Z" fill="currentColor"/>`;

/**
 * Cap on the rendered size of the built-in icon (see `sizeDefaultIcon`).
 */
const DEFAULT_ICON_MAX_SIZE = '20px';

interface HostIconStyle {
  /** Resolved `fill`, so the replacement stays visible against its background. */
  fill: string;
  /** Resolved `vertical-align`, so the replacement sits where the theme's own icons sit. */
  verticalAlign: string;
}

/**
 * Read the host icon's resolved style while it is still in the document.
 *
 * We carry resolved *values* across, never the host's attributes. Copying its
 * `class` looked tempting — it is where themes hang the icon's box model — but
 * a class re-imports everything else it carries: `.icon { opacity: .4 }` dims
 * our glyph, a class-borne `stroke` outlines our fill-only artwork, and a state
 * class like `is-hidden` on one half of a glyph pair hides us outright. Copying
 * `role`/`aria-*` is worse: `replaceWith` destroys the `<title>` that named the
 * host icon, so an inherited `role="img"` leaves the control an unnamed image.
 * Two resolved values are all the replacement actually needs.
 */
function readHostIconStyle(svg: Element): HostIconStyle {
  const cs = getComputedStyle(svg);
  return { fill: cs.fill, verticalAlign: cs.verticalAlign };
}

/**
 * Keep the enclosing control named after its icon is replaced.
 *
 * The replacement glyph is `aria-hidden`, which is right when the control is
 * named by something else — visible text, `aria-label`, `aria-labelledby`. But
 * a host like `<button><svg role="img"><title>Search</title>…</svg></button>`
 * is named *only* by that `<title>`, and `replaceWith` destroys it. Hiding the
 * replacement then leaves the control with no accessible name at all.
 *
 * So the displaced icon's name is read before it leaves the document and copied
 * onto the control as `aria-label`, but only when the control has no name of its
 * own — we never overwrite one the theme already set.
 *
 * `hasOwnAccessibleName` approximates the accname algorithm rather than
 * implementing it: it covers the sources a search control realistically uses.
 * Erring toward "already named" would risk clobbering a real name, so the
 * fallbacks are deliberately the cheap, unambiguous ones.
 */
function displacedIconName(svg: Element): string {
  const title = svg.querySelector('title')?.textContent?.trim();
  if (title) return title;
  return svg.getAttribute('aria-label')?.trim() ?? '';
}

function hasOwnAccessibleName(control: Element): boolean {
  if (control.getAttribute('aria-label')?.trim()) return true;
  if (control.getAttribute('aria-labelledby')?.trim()) return true;
  if (control.getAttribute('title')?.trim()) return true;

  // Visible text inside the control, ignoring the icon we are about to replace.
  const clone = control.cloneNode(true) as Element;
  clone.querySelectorAll('svg').forEach((el) => el.remove());
  return !!clone.textContent?.trim();
}

function preserveAccessibleName(control: Element, displaced: Element): void {
  if (hasOwnAccessibleName(control)) return;
  const name = displacedIconName(displaced);
  if (name) control.setAttribute('aria-label', name);
}

/** Build the built-in glyph. Total by construction — no parse step to fail. */
function buildDefaultIcon(): SVGSVGElement {
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('width', SEARCH_ICON_BOX);
  svg.setAttribute('height', SEARCH_ICON_BOX);
  svg.setAttribute('viewBox', SEARCH_ICON_VIEWBOX);
  svg.setAttribute('fill', 'none');
  // Decorative: the enclosing control conveys the action. The host icon's own
  // `<title>` does not survive `replaceWith`, so `preserveAccessibleName` copies
  // it onto the control first when that control has no name of its own.
  svg.setAttribute('aria-hidden', 'true');
  svg.innerHTML = SEARCH_ICON_PATHS;
  return svg;
}

/**
 * Keep the built-in glyph square, without dictating its size.
 *
 * The theme's own element-level `svg` rules still apply to our replacement, and
 * a host `height` rule (e.g. `height: 23px`) against our square viewBox
 * letterboxes the artwork — measured 20x23 on one storefront. Inline `height:
 * auto` outranks that rule (though not an `!important` one) and lets the
 * intrinsic 1:1 aspect derive the height. The width stays a *cap*, not a pin,
 * so a theme whose element-level rules size icons below 20px can still size
 * ours down; class-based sizing cannot reach us, since the class is not copied.
 *
 * `align-self` is set because `height: auto` is precisely what makes a flex
 * parent's default `align-items: stretch` apply — the presentation attribute
 * this replaced supplied a definite height and suppressed it. Without this a
 * flex search button stretches the box on the cross axis and the artwork
 * letterboxes inside it, which is the symptom we are removing.
 */
function sizeDefaultIcon(svg: SVGElement): void {
  svg.style.maxWidth = DEFAULT_ICON_MAX_SIZE;
  svg.style.height = 'auto';
  svg.style.alignSelf = 'center';
}

/**
 * Fills that carry no usable intent, so the glyph should inherit `currentColor`
 * from its button instead.
 *
 * `black` is here because it is the *initial* value of `fill`: a theme that
 * paints its artwork on the `<path>` children leaves the `<svg>` root computing
 * `rgb(0, 0, 0)`, which is indistinguishable from "unset". Transferring it
 * hard-paints our glyph black — invisible on a dark header. Inheriting is the
 * better guess in that case. Zero-alpha is listed for the same reason in the
 * other direction: copying it renders nothing at all.
 */
const UNUSABLE_HOST_FILL = /^(none|transparent|rgb\(0,\s*0,\s*0\)|rgba\([^)]*,\s*0(\.0+)?\s*\))$/i;

/**
 * Repaint the glyph in the host icon's colour. Our paths use
 * `fill="currentColor"`, so carrying the resolved fill onto `color` keeps the
 * same visible colour (e.g. a dark icon on a light search button). A fill that
 * expresses no intent is skipped, leaving the glyph to inherit currentColor.
 */
function applyHostFill(svg: SVGElement, hostFill: string): void {
  if (hostFill && !UNUSABLE_HOST_FILL.test(hostFill)) {
    svg.style.color = hostFill;
  }
}

/**
 * Sit the replacement where the theme's own icons sit.
 *
 * A bare `<svg>` is `vertical-align: baseline`, which hangs it off the text
 * baseline of the button's line box — measured 5.5px above centre. Where the
 * host resolves to anything else (Stencil's `.icon` uses `middle`; Bootstrap
 * Icons and Font Awesome use `-0.125em`, which a browser absolutises to px) we
 * transfer that resolved value, so our glyph lines up with its neighbours
 * instead of fighting them. The value is transferred rather than inherited via
 * `class`, so none of the theme's other icon styling comes with it.
 *
 * A host that resolves to `baseline` is treated as stating nothing, because
 * after `getComputedStyle` an explicit `vertical-align: baseline` and no
 * declaration at all are the same string. That is the one case we override:
 * baseline is the value that produces the bug, so honouring it would reinstate
 * the 5.5px hang for every theme that simply never set the property.
 */
function alignIconToHost(svg: SVGElement, hostVerticalAlign: string): void {
  const stated = hostVerticalAlign && hostVerticalAlign !== 'baseline';
  svg.style.verticalAlign = stated ? hostVerticalAlign : 'middle';
}

// ── Class ──────────────────────────────────────────────────────────

export class BCSearchIntegration implements SearchIntegration {
  private root: Root | null = null;
  private mountedContainer: HTMLElement | null = null;
  private mobileIntegration: BCMobileSearchIntegration | null = null;
  private handleClose: (() => void) | null = null;
  private _eventListeners: Array<{
    element: EventTarget;
    event: string;
    handler: EventListener;
    options?: boolean | AddEventListenerOptions;
  }> = [];

  initialized = false;

  private omniguideConfig: OmniguideConfig;
  private platformAdapter: PlatformAdapter;
  private storageAdapter?: StorageAdapter;
   
  private containerComponent?: React.ComponentType<any>;
  private components?: OmniguideComponentOverrides;
  private skipDomSetup: boolean;

  constructor({ config, platformAdapter, storageAdapter, ContainerComponent, components, skipDomSetup }: BCSearchIntegrationConfig) {
    this.omniguideConfig = config;
    this.platformAdapter = platformAdapter;
    this.storageAdapter = storageAdapter;
    this.containerComponent = ContainerComponent;
    this.components = components;
    this.skipDomSetup = skipDomSetup ?? false;
  }

  init(): boolean {
    const selectors = this.omniguideConfig.selectors ?? {};
    const rootId = selectors.rootContainer ?? 'ai-search-root';
    const existingContainer = document.getElementById(rootId);

    if (this.root && this.mountedContainer && this.mountedContainer === existingContainer && document.body.contains(this.mountedContainer)) {
      this.initialized = true;
      return true;
    }

    if (this.root && this.mountedContainer !== existingContainer) {
      try { this.root.unmount(); } catch { /* ignore */ }
      this.mountedContainer?.removeAttribute(MOUNTED_ATTR);
      this.root = null;
      this.mountedContainer = null;
    }

    this.createContainer(rootId);
    this.mountComponent(rootId);
    this.hideDefaultSearch(rootId);

    if (!this.skipDomSetup) {
      this.overrideSearchBehavior();
      this.swapSearchIcon();
      this.mobileIntegration = new BCMobileSearchIntegration(this, this.omniguideConfig);
    }

    const websiteId = this.omniguideConfig.websiteId;
    this.handleClose = () => {
      // Only remove class if we own the active state
      if (document.body.getAttribute('data-omniguide-search') === websiteId) deactivateSearchBody();
      restoreFocus();
    };
    window.addEventListener('closeAISearch', ((e: CustomEvent) => {
      // Filter: only respond to our own instance's events
      if (e.detail?.websiteId && e.detail.websiteId !== websiteId) return;
      this.handleClose!();
    }) as EventListener);

    this.initialized = true;
    return true;
  }

  openSearch(query = '', source = 'unknown'): void {
    if (!source.endsWith('_input_focus')) forgetOpener();
    activateSearchBody(this.omniguideConfig.websiteId);
    window.dispatchEvent(new CustomEvent('openAISearch', {
      detail: { query, source, websiteId: this.omniguideConfig.websiteId },
    }));
  }

  /**
   * Opens straight into the assistant with `query` as the shopper's first
   * message, skipping the search step — for a host entry point that has
   * already collected the query, such as its own autocomplete. Without a query
   * it is `openSearch`, and so it is in non-conversational search mode, where
   * there is no assistant to skip to. Never sends over a streaming answer or
   * repeats the last question (see BCSearchContainer).
   */
  askAssistant(query = '', source = 'unknown'): void {
    forgetOpener();
    activateSearchBody(this.omniguideConfig.websiteId);
    window.dispatchEvent(new CustomEvent('openAISearch', {
      detail: { query, source, websiteId: this.omniguideConfig.websiteId, ask: true },
    }));
  }

  private createContainer(rootId: string): void {
    if (document.getElementById(rootId)) return;
    const container = document.createElement('div');
    container.id = rootId;
    document.body.appendChild(container);
  }

  private mountComponent(rootId: string): void {
    const container = document.getElementById(rootId);
    if (container && !container.hasAttribute(MOUNTED_ATTR)) {
      container.setAttribute(MOUNTED_ATTR, 'true');
      this.root = createRoot(container);
      this.mountedContainer = container;

      const Container = this.containerComponent ?? BCSearchContainer;
      const providerProps: OmniguideProviderProps = {
        config: this.omniguideConfig,
        platformAdapter: this.platformAdapter,
        storageAdapter: this.storageAdapter,
        components: this.components,
        children: <Container />,
      };

      // Synchronous, effects included: the container's `openAISearch` listener has
      // to exist when init() returns, or an open fired in the meantime (a click
      // on the box during page load, the loader's first open) is dropped.
      flushSync(() => this.root!.render(<OmniguideProvider {...providerProps} />));
    }
  }

  private hideDefaultSearch(rootId: string): void {
    const selectors = this.omniguideConfig.selectors ?? {};
    const quickSearchResults = selectors.quickSearchResults ?? '.quickSearchResults, [data-search="quickResults"]';
    // The anchored dropdown is not a modal. SearchUI deliberately skips its
    // body-scroll-lock and focus-trap for it so the page stays usable behind
    // the panel; a static rule here would lock the page anyway and the store
    // reads as frozen — nothing scrolls, and the host's own search box is
    // hidden by then. Once a query is sent the panel becomes the centered
    // modal and SearchUI's own lock takes over, which is state-aware.
    // The sheet (SOI-2438) scrolls itself too; hiding the page's overflow
    // blinked its scrollbar on every open and close.
    const anchored = !!this.omniguideConfig.ui?.anchoredSearch;
    const sheet = !!this.omniguideConfig.ui?.searchSheet;
    const pageScrollLock = anchored || sheet ? '' : 'body.ai-search-active { overflow: hidden; }';

    const style = document.createElement('style');
    const quickSearchSelectors = quickSearchResults
      .split(',')
      .map((s: string) => `body.ai-search-active ${s.trim()}`)
      .join(',\n            ');

    style.textContent = `
      ${quickSearchSelectors} {
        display: none !important;
      }
      ${pageScrollLock}
      #${rootId} {
        z-index: 10000;
      }
    `;
    document.head.appendChild(style);
  }

  private swapSearchIcon(): void {
    const selectors = this.omniguideConfig.selectors ?? {};
    const expandSelector = selectors.searchExpandButton ?? '#quick-search-expand';
    // Resolve via querySelector (not getElementById) so a class/attribute
    // selector works — e.g. a BigCommerce theme whose search button has no id.
    // An `#id` selector still behaves exactly as before.
    const searchExpand = document.querySelector(expandSelector);
    if (!searchExpand) return;

    const existingSvg = searchExpand.querySelector('svg');
    if (!existingSvg) return;

    const host = readHostIconStyle(existingSvg);
    preserveAccessibleName(searchExpand, existingSvg);
    const aiSearchIcon = buildDefaultIcon();

    sizeDefaultIcon(aiSearchIcon);
    applyHostFill(aiSearchIcon, host.fill);
    alignIconToHost(aiSearchIcon, host.verticalAlign);

    existingSvg.replaceWith(aiSearchIcon);
  }

  // Typeahead tenants take the header box at every width (SOI-2436); the rest keep
  // the theme's own phone search. The mobile menu's field is BCMobileSearchIntegration's.
  private overrideSearchBehavior(): void {
    if (!this.omniguideConfig.ui?.typeahead && window.innerWidth <= 767) return;
    if (this.isWordPressEnvironment()) {
      this.overrideWordPressSearch();
    } else {
      this.overrideDesktopSearch();
    }
  }

  private isWordPressEnvironment(): boolean {
    const selectors = this.omniguideConfig.selectors ?? {};
    const wpSearchButton = selectors.wordpress?.searchButton ?? '.header-search-btn';
    return (
      window.location.pathname.includes('/blog') ||
      document.querySelector(wpSearchButton) !== null ||
      document.body.classList.contains('blog')
    );
  }

  private overrideWordPressSearch(): void {
    const selectors = this.omniguideConfig.selectors ?? {};
    const wp = selectors.wordpress ?? {};
    const wpSearchButton = wp.searchButton ?? '.header-search-btn';
    const wpSearchForms = wp.searchForms ?? '.header-search form, form.search-form';
    const wpSearchInputs = wp.searchInputs ?? '.header-search input[type="search"], .search-field';

    document.querySelectorAll(wpSearchButton).forEach((button) => {
      this._addTrackedListener(button, 'click', ((e: Event) => {
        e.preventDefault();
        e.stopImmediatePropagation();
        this.openSearch('', 'wordpress_search_button');
      }) as EventListener, true);
    });

    document.querySelectorAll(wpSearchForms).forEach((form) => {
      this._addTrackedListener(form, 'submit', ((e: Event) => {
        e.preventDefault();
        e.stopImmediatePropagation();
        const input = form.querySelector('input[type="search"], .search-field') as HTMLInputElement | null;
        const query = input?.value ?? '';
        this.openSearch(query, 'wordpress_search_form_submit');
        if (input) input.value = '';
      }) as EventListener, true);
    });

    document.querySelectorAll(wpSearchInputs).forEach((input) => {
      this._addTrackedListener(input, 'focus', ((e: Event) => {
        rememberOpener(e.target as HTMLElement);
        e.preventDefault();
        e.stopImmediatePropagation();
        (e.target as HTMLElement)?.blur();
        this.openSearch('', 'wordpress_search_input_focus');
      }) as EventListener, true);
    });
  }

  private overrideDesktopSearch(): void {
    const selectors = this.omniguideConfig.selectors ?? {};
    const searchToggles = selectors.searchToggles ?? '.navUser-action--quickSearch, [aria-label="Search toggle"]';
    const searchInputs = selectors.searchInputs ?? 'input[name="search_query"]';
    const searchForms = selectors.searchForms ?? 'form[action="/search.php"], form[data-search="quickSearch"]';
    const mobileMenu = selectors.mobileMenu ?? '#mobileMenu, .mobileMenu-search';

    document.querySelectorAll(searchToggles).forEach((toggle) => {
      this._addTrackedListener(toggle, 'click', ((e: Event) => {
        e.preventDefault();
        e.stopImmediatePropagation();
        this.openSearch('', 'nav_search_button');
      }) as EventListener, true);
    });

    const isInMobileMenu = (el: Element) => {
      const menuSelectors = mobileMenu.split(',').map((s: string) => s.trim());
      return menuSelectors.some((selector: string) => el.closest(selector));
    };

    document.querySelectorAll(searchInputs).forEach((input) => {
      if (isInMobileMenu(input)) return;
      const open = (el: HTMLElement) => {
        rememberOpener(el);
        el.blur();
        // Typed before the SDK bound: carry it into the search, as submit does.
        const query = (el as HTMLInputElement).value;
        (el as HTMLInputElement).value = '';
        this.openSearch(query, 'search_input_focus');
      };
      this._addTrackedListener(input, 'focus', ((e: Event) => {
        e.preventDefault();
        e.stopImmediatePropagation();
        open(e.target as HTMLElement);
      }) as EventListener, true);
      // Clicked while the page was loading: the box already has focus, so no
      // focus event will come and the click would do nothing.
      if (document.activeElement === input) open(input as HTMLElement);
    });

    document.querySelectorAll(searchForms).forEach((form) => {
      if (isInMobileMenu(form)) return;
      this._addTrackedListener(form, 'submit', ((e: Event) => {
        e.preventDefault();
        e.stopImmediatePropagation();
        const firstInputSelector = (searchInputs.split(',')[0] ?? searchInputs).trim();
        const input = form.querySelector(firstInputSelector) as HTMLInputElement | null;
        const query = input?.value ?? '';
        this.openSearch(query, 'search_form_submit');
        if (input) input.value = '';
      }) as EventListener, true);
    });
  }

  private _addTrackedListener(
    element: EventTarget,
    event: string,
    handler: EventListener,
    options?: boolean | AddEventListenerOptions,
  ): void {
    element.addEventListener(event, handler, options);
    this._eventListeners.push({ element, event, handler, options });
  }

  destroy(): void {
    if (this.root) {
      this.root.unmount();
      this.mountedContainer?.removeAttribute(MOUNTED_ATTR);
      this.mountedContainer = null;
      this.root = null;
    }

    if (this.mobileIntegration) {
      this.mobileIntegration.destroy();
    }

    this._eventListeners.forEach(({ element, event, handler, options }) => {
      element.removeEventListener(event, handler, options);
    });
    this._eventListeners = [];

    if (this.handleClose) {
      window.removeEventListener('closeAISearch', this.handleClose as EventListener);
    }
    // Only remove class if we own the active state
    if (document.body.getAttribute('data-omniguide-search') === this.omniguideConfig.websiteId) deactivateSearchBody();
  }
}
