/**
 * SearchSheetLogo — the slot in the search sheet's upper-left corner
 * (SOI-2438). Override it through the component map (`SearchSheetLogo`) to put
 * any markup there. This default shows `ui.searchSheetLogo`: a copy of the
 * storefront's own logo element (`selector`), or else an image (`src`).
 */

import React, { useEffect, useRef } from 'react';
import { logger, safeHref } from '@swiftotter/omniguide-core';

export interface SheetLogoConfig {
    /** CSS selector for the page's logo; the sheet shows a copy of it, so it matches the header. */
    selector?: string;
    src?: string;
    alt?: string;
    /** Makes an image logo a link, usually to the home page. */
    href?: string;
}

export interface SearchSheetLogoProps {
    logo?: SheetLogoConfig;
}

export const SearchSheetLogo: React.FC<SearchSheetLogoProps> = ({ logo }) => {
    if (logo?.selector) return <ClonedLogo selector={logo.selector} />;
    if (!logo?.src) return null;
    const img = <img className="omniguide-sheet__logo" src={logo.src} alt={logo.alt ?? ''} />;
    // Config, but still a navigation target: an unsafe scheme renders the image unlinked.
    const href = safeHref(logo.href);
    if (logo.href && !href) logger.warn('searchSheetLogo.href is not a safe navigation URL; the logo renders unlinked.');
    return href ? <a className="omniguide-sheet__logo-link" href={href}>{img}</a> : img;
};

/**
 * A deep copy, not a move: the header keeps its logo. Nothing renders when
 * nothing matches. The copy is decoration: ids are stripped so they stay
 * unique, and it is hidden from assistive tech (the header has the original).
 */
const ClonedLogo: React.FC<{ selector: string }> = ({ selector }) => {
    const ref = useRef<HTMLDivElement>(null);
    useEffect(() => {
        const source = document.querySelector(selector);
        const host = ref.current;
        if (!source) logger.warn(`searchSheetLogo: no element matches selector "${selector}" — the sheet's logo slot is empty.`);
        if (!source || !host) return;
        const copy = source.cloneNode(true) as Element;
        [copy, ...copy.querySelectorAll('[id]')].forEach((el) => el.removeAttribute('id'));
        host.replaceChildren(copy);
        host.setAttribute('inert', ''); // aria-hidden must not hold a focusable link
        return () => host.replaceChildren();
    }, [selector]);
    return <div ref={ref} className="omniguide-sheet__logo-clone" aria-hidden="true" />;
};
